import sys, time, serial

out, secs = sys.argv[1], float(sys.argv[2])
end = time.time() + secs
with open(out, "wb") as f:
    while time.time() < end:
        try:
            with serial.Serial("/dev/cu.usbmodem112401", 115200, timeout=1) as s:
                while time.time() < end:
                    f.write(s.read(4096))
                    f.flush()
        except (serial.SerialException, OSError):
            time.sleep(0.5)

