XLOCKMORE_HACK(thornbird, "Thornbird");
XLOCKMORE_HACK(spiral, "Spiral");
XLOCKMORE_HACK(sphere, "Sphere");
XLOCKMORE_HACK(discrete, "Discrete");
XLOCKMORE_HACK_WITH(galaxy, "Galaxy", kGalaxyOverrides);
XLOCKMORE_HACK(drift, "Drift");
XLOCKMORE_HACK(lightning, "Lightning");
XLOCKMORE_HACK(pacman, "Pacman");
XLOCKMORE_HACK(braid, "Braid");
XLOCKMORE_HACK(mountain, "Mountain");
extern const HackEntry substrate_hack;
extern const HackEntry epicycle_hack;
extern const HackEntry kaleidescope_hack;
extern const HackEntry deluxe_hack;
/* The xlockmore framework reads ncolors and cycles; Gears defines neither, and
 * nothing in Gears uses them. Its own 30 ms pause held a light layout to 11 to
 * 13 fps once the dirty rectangle made a frame 44 to 63 ms; 10 ms removes it. */
static const char *const kGearsOverrides[] = {"*ncolors: 64", "*cycles: 0",
                                              "*delay: 10000", NULL};
XLOCKMORE_HACK_WITH(gears, "Gears", kGearsOverrides);
/* The hack asks for a 40 ms pause after each frame, which held it to 10 fps
 * once a frame took 57 ms; 10 ms gives 14.6 fps. */
static const char *const kMorph3dOverrides[] = {"*ncolors: 64", "*cycles: 0",
                                                "*delay: 10000", NULL};
XLOCKMORE_HACK_WITH(morph3d, "Morph3D", kMorph3dOverrides);
/* The grid is ticks cubed points a frame: the default 30 (27,000) ran at 5.6
 * to 6 fps. 20 gives 8,000. */
static const char *const kCubicGridOverrides[] = {"*ncolors: 64", "*cycles: 0",
                                                  "*ticks: 20", NULL};
XLOCKMORE_HACK_WITH(cubicgrid, "CubicGrid", kCubicGridOverrides);
XLOCKMORE_HACK(forest, "Forest");
XLOCKMORE_HACK(laser, "Laser");
XLOCKMORE_HACK(lissie, "Lissie");
XLOCKMORE_HACK(rotor, "Rotor");
XLOCKMORE_HACK(scooter, "Scooter");
XLOCKMORE_HACK(grav, "Grav");
/* StonerView: An eccentric visual toy.
   Copyright 1998-2021 by Andrew Plotkin (erkyrath@eblong.com)
   Permission to use, copy, modify, distribute, and sell this software and its
   documentation for any purpose is hereby granted without fee, provided that
   the above copyright notice appear in all copies and that both that
   copyright notice and this permission notice appear in supporting
   documentation.  No representations are made about the suitability of this
   software for any purpose.  It is provided "as is" without express or 
   implied warranty.
*/
#ifndef __STONERVIEW_H__
# define __STONERVIEW_H__
typedef struct stonerview_state stonerview_state;
#include "stonerview-osc.h"
#include "stonerview-move.h"
struct stonerview_state {
  int wireframe;
  int transparent;
  /* The list of polygons. This is filled in by move_increment(), and rendered
     by perform_render(). */
  int num_els;
  stonerview_elem_t *elist;
  /* A linked list of all osc_t objects created. New objects are added
     to the end of the list, not the beginning. */
  osc_t *oscroot;
  osc_t **osctail;
  /* The polygons are controlled by four parameters. Each is represented by
     an osc_t object, which is just something that returns a stream of numbers.
     (Originally the name stood for "oscillator", but it does ever so much more
     now... see osc.c.)
     Imagine a cylinder with a vertical axis (along the Z axis), stretching
     from Z=1 to Z=-1, and a radius of 1.
  */
  osc_t *theta; /* Angle around the axis. This is expressed in
                   hundredths of a degree, so it's actually 0 to 36000. */
  osc_t *rad;   /* Distance from the axis. This goes up to 1000,
                   but we actually allow negative distances -- that just 
                   goes to the opposite side of the circle -- so the range
                   is really -1000 to 1000. */
  osc_t *alti;  /* Height (Z position). This goes from -1000 to 1000. */
  osc_t *color; /* Consider this to be an angle of a circle going 
                   around the color wheel. It's in tenths of a degree
                   (consistency is all I ask) so it ranges from 0 to 3600. */
};
#endif /* __STONERVIEW_H__ */

