#ifndef HACKS_HALO_CIRCLES_H
#define HACKS_HALO_CIRCLES_H

#include <math.h>

#include "core/canvas.h"
#include "x11shim/pixmap.h"
#include "x11shim/xshim.h"

/* A whole circle filled in float. The shim's canvas_fill_ellipse takes the
 * same row ends in double, which the S3 does in software: about 10 us a row,
 * and Halo fills a dozen circles of up to 466 rows each, every frame. Float
 * keeps the same pixels except where a row end lands within float rounding of
 * a half-way point. A partial arc takes the shim's path. */
static int halo_fill_circle(Display *dpy, Drawable d, GC gc, int x, int y,
                            unsigned int w, unsigned int h, int angle1,
                            int angle2) {
  if (angle2 < 360 * 64 && angle2 > -360 * 64)
    return (XFillArc)(dpy, d, gc, x, y, w, h, angle1, angle2);
  Canvas *const c = xshim_target(dpy, d);
  if (!c || w == 0 || h == 0 || w > 0x7FFFFFFFu || h > 0x7FFFFFFFu) return 0;
  const float cx = (float)x + ((float)w - 1.0f) / 2.0f;
  const float cy = (float)y + ((float)h - 1.0f) / 2.0f;
  const float rx = (float)w / 2.0f, ry = (float)h / 2.0f;
  int64_t y0 = y < 0 ? 0 : y, y1 = (int64_t)y + (int64_t)h - 1;
  if (y1 >= c->h) y1 = c->h - 1;
  for (int64_t yy = y0; yy <= y1; yy++) {
    const float ny = ((float)yy - cy) / ry;
    const float t = 1.0f - ny * ny;
    if (t < 0.0f) continue;
    const float half = rx * sqrtf(t);
    const int64_t xa = (int64_t)ceilf(cx - half), xb = (int64_t)floorf(cx + half);
    if (xb < xa) continue;
    canvas_fill_rect(c, (int)xa, (int)yy, (int)(xb - xa + 1), 1,
                     (uint16_t)gc->foreground);
  }
  return 0;
}

#endif
E
