  TEST_ASSERT_EQUAL_HEX64(0, XGetPixel(im, 3, 1));
  XDestroyImage(im);
}

void test_put_image_of_a_16_bit_image_writes_ordinary_rgb565_as_the_canvas_holds_it(void) {
