extern int loop_neighbors_in_use(void);
static Canvas cv;

void setUp(void) { TEST_ASSERT_EQUAL_INT(0, canvas_init(&cv, 466, 466, malloc)); }
void tearDown(void) { canvas_free(&cv); }

static int index_of(const char *name) {
  for (int i = 0; i < g_hack_count; i++)
    if (strcmp(g_hacks[i]->name, name) == 0) return i;
  return -1;
}

void test_probe(void) {
  FILE *f = fopen("$S/loop_probe.txt", "w");
  HackRunner *r = runner_create(&cv);
  for (int seed = 1; seed <= 40; seed++) {
    srandom(seed);
    runner_start(r, index_of("Loop"));
    for (int fr = 0; fr < 300; fr++) runner_step(r);
    long lit = 0;
    for (long i = 0; i < (long)cv.w * cv.h; i++) lit += cv.px[i] != 0;
    fprintf(f, "seed %d mode %d lit %ld\\n", seed, loop_neighbors_in_use(), lit);
  }
  runner_destroy(r);
  fclose(f);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_probe);
  return UNITY_END();
}
